import React, { useEffect, useState } from "react";
import axios from "axios";
import "../styles/ChatMain.css";

const ChatMain = ({ conversation, triggerRefresh }) => {
  const [messages, setMessages] = useState([]);
  const [newMsg, setNewMsg] = useState("");
  const user = JSON.parse(localStorage.getItem("user"));

  useEffect(() => {
    if (!conversation) return;

    const fetchMessages = async () => {
      try {
        const res = await axios.get(`http://localhost:5000/api/messages/${conversation._id}`);
        setMessages(res.data);
      } catch (err) {
        console.error("Error loading messages:", err);
      }
    };

    fetchMessages();
  }, [conversation]);

  const sendMessage = async () => {
    if (!newMsg.trim() || !conversation) return;

    const receiver = conversation.participants.find(id => id !== user.userId);

    const messageData = {
      conversationId: conversation._id,
      senderId: user.userId,
      senderUsername: user.username,
      receiverId: receiver,
      receiverUsername: conversation.participantUsernames.find(name => name !== user.username),
      text: newMsg,
    };

    try {
      await axios.post("http://localhost:5000/api/messages", messageData);
      setNewMsg("");
      triggerRefresh();
    } catch (err) {
      console.error("Error sending message:", err);
    }
  };

  return (
    <div className="chat-main">
      {conversation ? (
        <>
          <h3>Conversation with {
            conversation.participantUsernames.find(name => name !== user.username)
          }</h3>
          <div className="chat-messages">
            {messages.map((msg) => (
              <div key={msg._id} className={`msg-bubble ${msg.senderId === user.userId ? "sent" : "received"}`}>
                <p>{msg.text}</p>
                <span className="timestamp">{new Date(msg.timestamp).toLocaleString()}</span>
              </div>
            ))}
          </div>
          <div className="chat-input">
            <input
              type="text"
              placeholder="Type a message..."
              value={newMsg}
              onChange={(e) => setNewMsg(e.target.value)}
            />
            <button onClick={sendMessage}>Send</button>
          </div>
        </>
      ) : (
        <p>No conversation selected</p>
      )}
    </div>
  );
};

export default ChatMain;
